cd /app/work && python3 << 'EOF'
import json, os
from collections import defaultdict
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
notes=json.load(open('notes.json'))
bypat=defaultdict(list)
for n in notes:
    if n[0]!='?': bypat[n[0]].append(n)
meds={}
for l in open('Medication.ndjson'):
    d=json.loads(l); meds[d['id']]=d
def mname(m):
    for i in m.get('identifier',[]):
        if 'medication-name' in i['system']: return i['value']
    return None
mrs=defaultdict(list)
for l in open('MedicationRequest.ndjson'):
    r=json.loads(l)
    if r.get('authoredOn','')>='2025-01-01':
        mrs[r['subject']['reference'].split('/')[1]].append(r)
encs={}
for l in open('Encounter.ndjson'):
    d=json.loads(l); encs[d['id']]=d
conds=defaultdict(list)
for l in open('Condition.ndjson'):
    d=json.loads(l)
    conds[d['subject']['reference'].split('/')[1]].append(d)
ecgs=defaultdict(list)
for e in json.load(open('ecgs.json'))['ecgs']: ecgs[e['patient']].append(e)
labs=defaultdict(list)
for d in json.load(open('labs.json')):
    labs[d['subject']['reference'].split('/')[1]].append(d)
procs=defaultdict(list)
for l in open('Procedure.ndjson'):
    d=json.loads(l); procs[d['subject']['reference'].split('/')[1]].append(d)

os.makedirs('dossier',exist_ok=True)
def obsval(d):
    if 'valueQuantity' in d: return f"{d['valueQuantity'].get('value')} {d['valueQuantity'].get('unit','')}"
    if 'valueString' in d: return d['valueString']
    if 'valueCodeableConcept' in d: return json.dumps(d['valueCodeableConcept'].get('coding',[{}])[0].get('display'))
    return json.dumps({k:v for k,v in d.items() if k.startswith('value')})

for pid,p in pats.items():
    if p.get('deceasedDateTime'): continue
    f=open(f'dossier/{pid}.txt','w')
    W=lambda *a: print(*a,file=f)
    W('PATIENT',pid,p['birthDate'],p['gender'],p['name'][0]['family'])
    W('### CONDITIONS (with encounter date)')
    seen=set()
    for c in conds[pid]:
        e=encs.get((c.get('encounter') or {}).get('reference','').split('/')[-1])
        dt=(e or {}).get('period',{}).get('start','?')[:10]
        for cc in c['code']['coding']:
            k=(dt,cc.get('display'))
            if k in seen: continue
            seen.add(k)
            W(' ',dt,cc.get('display'),c['id'])
    W('### MEDICATION REQUESTS since 2025')
    for r in sorted(mrs[pid],key=lambda r:r['authoredOn']):
        mn=mname(meds[r['medicationReference']['reference'].split('/')[1]]) if 'medicationReference' in r else json.dumps(r.get('medicationCodeableConcept',{}).get('coding',[{}])[0].get('code'))
        vp=(r.get('dispenseRequest') or {}).get('validityPeriod') or {}
        W(' ',r['authoredOn'][:16],r['status'],(mn or '?'),'|',(r.get('dosageInstruction',[{}])[0].get('text') or ''),'| valid',vp.get('start','')[:10],'-',vp.get('end','')[:10],'|',r['id'])
    W('### ECGs')
    for e in sorted(ecgs[pid],key=lambda x:x['time']): W(' ',e['ecg'],e['time'])
    W('### LABS (INR/K/Mg) since 2025')
    for d in sorted(labs[pid],key=lambda d:d.get('effectiveDateTime','')):
        if d.get('effectiveDateTime','')<'2025-01-01': continue
        disp=d['code']['coding'][0].get('display')
        W(' ',d.get('effectiveDateTime','')[:16],disp,obsval(d),d['id'])
    W('### PROCEDURES since 2024')
    for d in sorted(procs[pid],key=lambda d:d.get('performedDateTime') or d.get('performedPeriod',{}).get('start','')):
        t=(d.get('performedDateTime') or d.get('performedPeriod',{}).get('start') or '')
        if t<'2024-01-01': continue
        W(' ',t[:10],json.dumps([cc.get('display') for cc in d['code']['coding']]),d['id'])
    W('### NOTES')
    for n in sorted(bypat[pid],key=lambda n:n[1]):
        W('-'*70)
        enc=(n[7] or {}).get('encounter',[{}])[0].get('reference','').split('/')[-1]
        e=encs.get(enc)
        W('NOTE',n[2],n[1],n[3],'role='+(n[4][0].get('valueCode') if n[4] else '?'),'author='+json.dumps(n[6]))
        if e: W('  ENC',enc,e['class']['code'],(e.get('serviceType') or {}).get('coding',[{}])[0].get('code'),e.get('period'))
        W(n[5])
    f.close()
print('done')
EOF
