import numpy as np, wfdb
from scipy import signal as sg

LEADS=['I','II','III','aVR','aVF','aVL','V1','V2','V3','V4','V5','V6']
IND=['I','II','V1','V2','V3','V4','V5','V6']  # independent leads

def load(path):
    r=wfdb.rdrecord(path)
    x=np.nan_to_num(r.p_signal.astype(float))
    return {n:x[:,i] for i,n in enumerate(r.sig_name)}, r.fs

def bp(x,fs,lo=0.5,hi=40):
    b,a=sg.butter(3,[lo/(fs/2),hi/(fs/2)],btype='band')
    return sg.filtfilt(b,a,x)

def notch_base(x,fs):
    # remove baseline wander with median filter
    w=int(0.6*fs)|1
    base=sg.medfilt(sg.medfilt(x,w),int(0.2*fs)|1)
    return x-base

def detect_r(sigs,fs):
    # composite derivative energy
    comp=np.zeros(len(sigs['II']))
    for n in IND:
        s=bp(sigs[n],fs,0.5,40)
        d=np.gradient(s)*fs
        comp+=d**2
    comp=np.sqrt(comp)
    w=int(0.08*fs)|1
    env=sg.convolve(comp,np.hanning(w)/np.hanning(w).sum(),mode='same')
    thr=0.3*np.percentile(env,99)
    pk,_=sg.find_peaks(env,height=thr,distance=int(0.2*fs))
    # refine to max |vm| within +-60ms
    vm=vecmag(sigs,fs)
    out=[]
    for p in pk:
        a=max(0,p-int(0.06*fs)); b=min(len(vm),p+int(0.06*fs))
        out.append(a+int(np.argmax(vm[a:b])))
    return np.array(sorted(set(out))), env

def vecmag(sigs,fs):
    acc=0
    for n in IND:
        s=bp(sigs[n],fs,0.5,40)
        acc=acc+s**2
    return np.sqrt(acc)

def median_beat(sigs,fs,rpeaks,pre=0.45,post=0.55):
    a=int(pre*fs); b=int(post*fs)
    segs={n:[] for n in LEADS}
    used=0
    for r in rpeaks:
        if r-a<0 or r+b>len(sigs['II']): continue
        used+=1
        for n in LEADS:
            s=notch_base(bp(sigs[n],fs,0.5,40),fs)
            segs[n].append(s[r-a:r+b])
    if used<1: return None,None,None
    med={n:np.median(np.vstack(segs[n]),axis=0) for n in LEADS}
    return med,a,used

def median_beat_fast(sigs,fs,rpeaks,pre=0.45,post=0.55):
    a=int(pre*fs); b=int(post*fs)
    filt={n:notch_base(bp(sigs[n],fs,0.5,40),fs) for n in LEADS}
    segs={n:[] for n in LEADS}
    cnt=0
    for r in rpeaks:
        if r-a<0 or r+b>len(sigs['II']): continue
        cnt+=1
        for n in LEADS: segs[n].append(filt[n][r-a:r+b])
    if cnt<1: return None,None,0
    med={n:np.median(np.vstack(segs[n]),axis=0) for n in LEADS}
    return med,a,cnt

def beat_vm(med):
    acc=0
    for n in IND: acc=acc+med[n]**2
    return np.sqrt(acc)
